import itertools

def solve_game(n):
    # State: (alice_nums, bob_nums, remaining_nums)
    # Numbers are 1-indexed.
    # Returns: 1 for Alice win, 0 for Draw, -1 for Alice loss

    memo = {}

    def get_result(alice_nums, bob_nums, remaining_nums, is_alice_turn):
        state = (tuple(sorted(alice_nums)), tuple(sorted(bob_nums)), tuple(sorted(remaining_nums)), is_alice_turn)
        if state in memo:
            return memo[state]

        if not remaining_nums:
            return 0

        # Possible moves for the current player
        moves = []
        current_nums = alice_nums if is_alice_turn else bob_nums
        for m in remaining_nums:
            # Rule (ii): cannot choose a number consecutive to any of those the player has already chosen.
            if not any(abs(m - x) == 1 for x in current_nums):
                moves.append(m)

        if not moves:
            # The player who cannot choose a number anymore loses the game.
            return -1 if is_alice_turn else 1

        results = []
        for m in moves:
            new_remaining = tuple(x for x in remaining_nums if x != m)
            if is_alice_turn:
                res = get_result(alice_nums + (m,), bob_nums, new_remaining, False)
            else:
                res = get_result(alice_nums, bob_nums + (m,), new_remaining, True)
            results.append(res)

        # Optimal play: 
        # 1. Try to win (move to a state that results in a loss for the other player)
        if is_alice_turn:
            if -1 in results:
                res = 1
            elif 0 in results:
                res = 0
            else:
                res = -1
        else:
            # Bob's perspective: 1 is Alice win, -1 is Alice loss (Bob win), 0 is draw
            # So Bob wants to reach -1.
            if -1 in results:
                res = -1
            elif 0 in results:
                res = 0
            else:
                res = 1

        memo[state] = res
        return res

    # The game starts with Alice's turn and all numbers available.
    return get_result((), (), tuple(range(1, n + 1)), True)

# Test for small n
for n in range(1, 8):
    res = solve_game(n)
    print(f"n={n}, Result={res}")
