def solve_game_fast(n):
    # alice_mask: bitmask of numbers chosen by Alice
    # bob_mask: bitmask of numbers chosen by Bob
    # turn: 0 for Alice, 1 for Bob
    memo = {}

    def get_result(alice_mask, bob_mask, turn):
        state = (alice_mask, bob_mask, turn)
        if state in memo:
            return memo[state]

        # Check if all numbers are chosen
        if (alice_mask | bob_mask) == (1 << n) - 1:
            return 0

        moves = []
        current_mask = alice_mask if turn == 0 else bob_mask
        for m in range(n):
            if not (alice_mask & (1 << m)) and not (bob_mask & (1 << m)):
                # Check rule (ii): no number consecutive to any chosen by the same player
                is_consecutive = False
                if m > 0 and (current_mask & (1 << (m - 1))):
                    is_consecutive = True
                if m < n - 1 and (current_mask & (1 << (m + 1))):
                    is_consecutive = True

                if not is_consecutive:
                    moves.append(m)

        if not moves:
            # The player who cannot choose a number anymore loses the game.
            return -1 if turn == 0 else 1

        results = []
        for m in moves:
            if turn == 0:
                results.append(get_result(alice_mask | (1 << m), bob_mask, 1))
            else:
                results.append(get_result(alice_mask, bob_mask | (1 << m), 0))

        # Optimal play
        if turn == 0:
            if -1 in results:
                res = 1
            elif 0 in results:
                res = 0
            else:
                res = -1
        else:
            if -1 in results:
                res = -1
            elif 0 in results:
                res = 0
            else:
                res = 1

        memo[state] = res
        return res

    return get_result(0, 0, 0)

